        );
        await connection.commit();
        return siguiente;
      } catch (err) {
        await connection.rollback();
        throw err;
      } finally {
        connection.release();
      }
    }
    const cfg = configLocalHacienda(idCompania);
    if (tipoDocumento === "03") return ++cfg.ultimoConsecutivoNc;
    return ++cfg.ultimoConsecutivoNd;
